// The `records` payload of the load benchmark (bench/README.md): realistic, compressible message
// text in which every message differs, generated byte for byte as bench/payload.py does. Each
// message is log records, one JSON object per line, appended until the message reaches its size
// and cut to exactly that size; the next message starts a new record.

/** The xorshift64 seed of worker 0, as 32-bit halves; worker i uses it plus i. */
const WorkerSeedHigh = 0x9e3779b9;
const WorkerSeedLow = 0x7f4a7c15;
const Services = [
  "checkout",
  "cart",
  "payments",
  "inventory",
  "search",
  "auth",
  "gateway",
  "notifier",
];
const Regions = ["us-east-1", "us-west-2", "eu-west-1", "eu-central-1", "ap-southeast-1"];
const Methods = ["GET", "POST", "PUT", "DELETE"];
const Routes = [
  "/api/v1/orders",
  "/api/v1/orders/{id}",
  "/api/v1/cart",
  "/api/v1/users/{id}",
  "/api/v1/search",
  "/healthz",
];
const Statuses = [200, 200, 200, 200, 200, 201, 204, 400, 404, 500];
const Hex = "0123456789abcdef";
const BaseTimestampMs = 1_790_000_000_000;
const TwoTo32 = 2 ** 32;

/** The payload of worker: next() returns its next message of size bytes. */
export function newPayload(kind, size, worker) {
  if (kind === "records") {
    const records = new Records(worker);
    return { next: () => records.message(size) };
  }
  const message = "x".repeat(size);
  return { next: () => message };
}

/**
 * A records generator. The 64-bit xorshift state is kept as two unsigned 32-bit halves, which
 * keeps it off BigInt: the page generates a message per operation inside the measured window.
 */
export class Records {
  #high;
  #low;
  #count = 0;

  /** The generator of worker's messages. */
  constructor(worker) {
    const low = WorkerSeedLow + worker;
    this.#low = low >>> 0;
    this.#high = (WorkerSeedHigh + Math.floor(low / TwoTo32)) >>> 0;
  }

  /** The next message, of size bytes. */
  message(size) {
    let message = "";
    while (message.length < size) {
      message += this.#record();
    }
    return message.slice(0, size);
  }

  /** Advances the state: x ^= x << 13; x ^= x >> 7; x ^= x << 17. */
  #step() {
    let high = this.#high;
    let low = this.#low;
    high = (high ^ ((high << 13) | (low >>> 19))) >>> 0;
    low = (low ^ (low << 13)) >>> 0;
    low = (low ^ ((low >>> 7) | (high << 25))) >>> 0;
    high = (high ^ (high >>> 7)) >>> 0;
    high = (high ^ ((high << 17) | (low >>> 15))) >>> 0;
    low = (low ^ (low << 17)) >>> 0;
    this.#high = high;
    this.#low = low;
  }

  /** The next state modulo n, for n small enough that every product stays an exact double. */
  #below(n) {
    this.#step();
    return ((this.#high % n) * (TwoTo32 % n) + (this.#low % n)) % n;
  }

  #between(low, high) {
    return low + this.#below(high - low + 1);
  }

  #pick(values) {
    return values[this.#below(values.length)];
  }

  #record() {
    const timestamp = BaseTimestampMs + this.#count * 13 + this.#between(0, 12);
    this.#count++;
    const service = this.#pick(Services);
    const region = this.#pick(Regions);
    const method = this.#pick(Methods);
    const route = this.#pick(Routes);
    const status = this.#pick(Statuses);
    const latency = this.#between(1, 2000);
    let trace = "";
    for (let i = 0; i < 32; i++) {
      trace += Hex[this.#below(16)];
    }
    const user = this.#between(1, 1_000_000);
    return (
      `{"ts":${timestamp},"service":"${service}","region":"${region}",` +
      `"method":"${method}","route":"${route}","status":${status},` +
      `"latency_ms":${latency},"trace":"${trace}","user":${user}}\n`
    );
  }
}
